// Mixes the music bed with the voiceover and ducks the bed under it.
//
// The VO is ONE continuous read (assets/vo-take.mp3, generated by vo-take.mjs), not one
// file per line: a single job keeps one performance, so the prosody doesn't reset between
// sentences. The take is cut at its own sentence pauses and the pieces are placed on the
// picture beats, so the read stays continuous while still hitting every visual.
//
// Beat -> cue mapping (1s of film = 1s of audio, no drift):
//   build 1.1   brand card 6.05   what 9.0   fit 13.85   how 17.55
//   proof 23.5  studio 29.15      end 34.05  close 37.15
import { execFileSync } from "node:child_process";
import { existsSync } from "node:fs";

const TAKE = "assets/vo-take.mp3";
const BED = "../soundtrack.wav";
const OUT = "mixed.wav";
const DUR = 42;

// Cut points in the take = the middle of each sentence pause measured with
// `silencedetect=noise=-40dB:d=0.12` (pauses are an even 0.43-0.47 s).
const SEGS = [
  { from: 0.00, to: 4.78,  t: 1.10 },  // agents can't speak
  { from: 4.78, to: 6.62,  t: 6.05 },  // that's where Koe comes in
  { from: 6.62, to: 10.24, t: 9.00 },  // what Koe is
  { from: 10.24, to: 11.95, t: 13.85 }, // point your agent at it
  { from: 11.95, to: 15.73, t: 17.55 }, // key, connect, voiceover
  { from: 15.73, to: 19.97, t: 23.50 }, // no account / no bill / nothing to install
  { from: 19.97, to: 23.54, t: 29.15 }, // the studio playground
  { from: 23.54, to: 26.34, t: 34.05 }, // a host of voices, one URL
  { from: 26.34, to: 29.568, t: 37.15 }, // free to start, give your agent a voice
];

const BED_GAIN = 0.85;  // -1.4 dB: leaves room for the voice without burying the track
const TAKE_LUFS = -18.19;
const VO_LUFS = -18.0;
const VO_GAIN = 1.4;

// Trim the piece's own edges to a fixed 50 ms head / 80 ms tail so every entry is identical.
const TRIM =
  "silenceremove=start_periods=1:start_threshold=-45dB:start_silence=0.05," +
  "areverse,silenceremove=start_periods=1:start_threshold=-45dB:start_silence=0.08,areverse";

const gainDb = (VO_LUFS - TAKE_LUFS).toFixed(2);

const vo = SEGS.map((s, i) => {
  const ms = Math.round(s.t * 1000);
  return `[0:a]atrim=start=${s.from}:end=${s.to},asetpts=PTS-STARTPTS,` +
    `aresample=48000,aformat=sample_fmts=fltp:channel_layouts=stereo,${TRIM},` +
    `volume=${gainDb}dB,volume=${VO_GAIN},adelay=${ms}|${ms}[v${i}]`;
});

const bus = SEGS.map((_, i) => `[v${i}]`).join("") + `amix=inputs=${SEGS.length}:normalize=0:dropout_transition=0`;
const graph = [
  ...vo,
  `${bus},asplit=2[vo][sc]`,
  // sidechaincompress stops when its shortest input ends, so pad the trigger to the full film
  `[sc]apad=whole_dur=${DUR}[scp]`,
  `[1:a]aresample=48000,aformat=sample_fmts=fltp:channel_layouts=stereo,volume=${BED_GAIN},apad[bed]`,
  // sidechain compress the bed with the voice as the trigger: ~10 dB of duck while speaking
  `[bed][scp]sidechaincompress=threshold=0.02:ratio=8:attack=8:release=280:makeup=1,apad=whole_dur=${DUR}[duck]`,
  `[duck][vo]amix=inputs=2:normalize=0:dropout_transition=0,alimiter=limit=0.95:level=false[mix]`,
].join(";");

for (const f of [TAKE, BED]) if (!existsSync(f)) throw new Error(`missing ${f}`);

execFileSync("ffmpeg", [
  "-y", "-hide_banner", "-loglevel", "error",
  "-i", TAKE, "-i", BED,
  "-filter_complex", graph,
  "-map", "[mix]",
  "-t", String(DUR),
  "-ar", "48000", "-ac", "2", "-c:a", "pcm_s16le",
  OUT,
], { stdio: "inherit" });

console.log(`${OUT} — one take cut into ${SEGS.length} cues, bed ${BED_GAIN}x, voice ${VO_LUFS} LUFS x${VO_GAIN}, ${DUR}s`);
